"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["9102"],{44158(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.ato_duplicado_na_etapa","status":422,"titulo":"A etapa declara o mesmo tipo de ato com o mesmo papel mais de uma vez"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.ato_duplicado_na_etapa","requisitos":["UNI-REQ-0157"],"oQueAconteceu":["Uma etapa declara, entre os produtos que publica, o mesmo tipo de ato com o mesmo papel duas\\nou mais vezes.","O tipo de ato identifica a mat\xe9ria publicada, e o papel diz se a publica\xe7\xe3o \xe9 preliminar,\\nque abre o prazo de recurso, definitiva, que fecha o ciclo recursal, ou sem papel. Declarado\\nduas vezes com o mesmo papel, a etapa passa a anunciar duas publica\xe7\xf5es iguais da mesma\\nmat\xe9ria, e o recurso n\xe3o teria como saber a partir de qual delas contar o prazo.","Publicar o preliminar e o definitivo da mesma mat\xe9ria **n\xe3o** cai aqui: a etapa declara o\\nmesmo tipo de ato duas vezes, uma com o papel preliminar e outra com o papel definitivo. \xc9 o\\ntipo de ato que liga o definitivo ao preliminar que ele espera. A regra \xe9 a mesma da [`fase\\ndo cronograma`](/erros/uniplus.selecao.fase_cronograma.ato_duplicado_na_fase)."],"comoResolver":["Remova a declara\xe7\xe3o repetida. A mensagem da recusa nomeia o c\xf3digo do ato que aparece mais\\nde uma vez com o mesmo papel na etapa.","Se a inten\xe7\xe3o era anunciar duas publica\xe7\xf5es diferentes da etapa, declare o tipo de ato de\\ncada uma. Se era anunciar o preliminar e o definitivo da mesma mat\xe9ria, declare o mesmo tipo\\nde ato duas vezes, uma com cada papel."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);